import SwiftUI

struct BoardLibrary:View{@EnvironmentObject var store:BoardStore;@State private var search=""
 var results:[Board]{store.boards.filter{search.isEmpty || $0.searchableText.localizedCaseInsensitiveContains(search)}}
 var body:some View{ZStack{Color(nsColor:.windowBackgroundColor).ignoresSafeArea();VStack(spacing:0){HStack{Text("Boards").font(.largeTitle.bold());Spacer();TextField("Search boards",text:$search).textFieldStyle(.roundedBorder).frame(width:240);Button("New"){store.newBoard();store.showLibrary=false};Button(action: { store.showLibrary = false }) { Image(systemName: "xmark") }}.padding(24);ScrollView{LazyVGrid(columns:[GridItem(.adaptive(minimum:240),spacing:20)],spacing:20){ForEach(results){b in BoardCard(board:b)}}.padding(24)}}}.transition(.opacity)} }
struct BoardCard:View{@EnvironmentObject var store:BoardStore;let board:Board
 var body:some View{Button{store.open(board)}label:{VStack(alignment:.leading,spacing:0){ZStack{Color(nsColor:.textBackgroundColor);CanvasThumbnail(board:board).padding(8)}.frame(height:150);Divider();HStack{VStack(alignment:.leading){Text(board.name).font(.headline).lineLimit(1);Text(board.modifiedAt,style:.relative).font(.caption).foregroundStyle(.secondary)};Spacer();if board.favorite{Image(systemName:"star.fill").foregroundStyle(.orange)}}.padding(12)}}.buttonStyle(.plain).background(.background).clipShape(RoundedRectangle(cornerRadius:10)).overlay(RoundedRectangle(cornerRadius:10).stroke(.separator.opacity(0.5),lineWidth:0.5)).contextMenu{Button(board.favorite ? "Unfavorite":"Favorite"){if let i=store.boards.firstIndex(where:{$0.id==board.id}){store.boards[i].favorite.toggle()}};Button("Duplicate"){store.duplicate(board)};Button("Delete",role:.destructive){store.delete(board)}}} }
struct CanvasThumbnail:View{let board:Board;var body:some View{Canvas{ctx,size in for e in board.elements.prefix(100){let r=e.bounds.cgRect;if e.kind == .stroke{var path=Path();if let f=e.points.first{path.move(to:f.cgPoint);for p in e.points.dropFirst(){path.addLine(to:p.cgPoint)}};ctx.stroke(path,with:.color(.primary.opacity(0.55)),lineWidth:max(1,e.width/2))}else{ctx.stroke(Path(r),with:.color(.secondary.opacity(0.5)),lineWidth:1)}}}}}
